const fs=require('fs'),cp=require('child_process'),crypto=require('crypto');
const TARGET=process.env.TARGET_FILE,SHA=process.env.TARGET_SHA,BLOB=process.env.TARGET_BLOB,HASH=process.env.TARGET_HASH,BYTES=Number(process.env.TARGET_BYTES),assert=(x,m)=>{if(!x)throw new Error(m)},sh=c=>cp.execSync(c,{encoding:'utf8'}).trim();
const SEL='body.home-index-shell .professional-showcase > .professional-showcase__rail > .professional-showcase__track';
function parse(src){const ls=src.split(/\r?\n/);let depth=0,sp=[],ap=[],sel=null;const ds=[],stack=[],re=/^\s*([\w-]+)\s*:\s*(.*?)\s*;\s*$/,norm=p=>p.join(' ').replace(/\{\s*$/,'').replace(/\s+/g,' ').trim();for(let i=0;i<ls.length;i++){const line=ls[i],t=line.trim(),o=(line.match(/\{/g)||[]).length,c=(line.match(/\}/g)||[]).length;if(!sel){if(ap.length){if(t)ap.push(t);if(line.includes('{')){stack.push({type:'at',header:norm(ap),depthBefore:depth});ap=[]}}else if(t.startsWith('@')&&!t.includes(';')){if(line.includes('{'))stack.push({type:'at',header:norm([t]),depthBefore:depth});else ap=[t]}else if(sp.length){if(t)sp.push(t);if(line.includes('{')){sel=norm(sp);sp=[];stack.push({type:'rule',selector:sel,depthBefore:depth})}}else if(t&&!t.startsWith('/*')&&!t.startsWith('*')&&t!=='*/'&&t!=='}'&&!t.startsWith('@')&&!line.includes(';')){sp=[t];if(line.includes('{')){sel=norm(sp);sp=[];stack.push({type:'rule',selector:sel,depthBefore:depth})}}}if(sel){const m=line.match(re);if(m){const raw=m[2].trim(),important=/\s*!important\s*$/i.test(raw),context=stack.filter(x=>x.type==='at').map(x=>x.header).join(' || ');ds.push({line:i+1,selector:sel,property:m[1].toLowerCase(),value:raw,important,context})}}depth+=o-c;while(stack.length&&depth<=stack.at(-1).depthBefore){const p=stack.pop();if(p.type==='rule')sel=null}}const last=new Map(),dead=[];for(let i=ds.length-1;i>=0;i--){const d=ds[i],k=`${d.context} >>> ${d.selector} >>> ${d.property}`,l=last.get(k);if(l&&(!d.important||l.important))dead.push({...d,winnerLine:l.line,winnerValue:l.value,winnerImportant:l.important});if(!l||d.important||!l.important)last.set(k,d)}return{declarations:ds,dead:dead.sort((a,b)=>a.line-b.line)}}
assert(sh('git rev-parse HEAD')===SHA,'wrong parent SHA');assert(sh(`git hash-object ${TARGET}`)===BLOB,'parent blob drift');const src=fs.readFileSync(TARGET,'utf8'),p=parse(src);assert(p.declarations.length===214&&p.dead.length===1,'parent parse drift');const d=p.dead[0];assert(d.line===323&&d.selector===SEL&&d.property==='gap'&&d.value==='14px'&&!d.important,'dead row drift');assert(d.context.includes('@media (max-width: 760px)'),'context drift');assert(d.winnerLine===366&&d.winnerValue==='var(--professional-showcase-gap)'&&!d.winnerImportant,'winner drift');const nl=/\r?\n$/.test(src),ls=src.split(/\r?\n/);if(nl&&ls.at(-1)==='')ls.pop();assert(ls[d.line-1]?.trim()==='gap: 14px;',`source mismatch ${d.line}`);ls.splice(d.line-1,1);fs.writeFileSync(TARGET,ls.join('\n')+(nl?'\n':''));const q=parse(fs.readFileSync(TARGET,'utf8')),stat=sh(`git diff --numstat -- ${TARGET}`).split(/\s+/),buf=fs.readFileSync(TARGET),hash=crypto.createHash('sha256').update(buf).digest('hex');assert(q.declarations.length===213&&q.dead.length===0,'candidate parse drift');assert(stat[0]==='0'&&stat[1]==='1'&&stat[2]===TARGET,'diff drift');assert(hash===HASH&&buf.length===BYTES,`identity drift ${hash}/${buf.length}`);console.log(`PROMOTION BUILD PASS|hash=${hash}|bytes=${buf.length}|files=1|additions=0|deletions=1|decl=214->213|dead=1->0|families=1|identical=0|changed=1|context=max760`);
